class TestValidationPipeline:
    async def test_stages_run_in_order(self):
        pipeline = ValidationPipeline([SyntaxStage(), SchemaStage()])
        doc = PlanDocument.from_json(
            json.dumps(
                {
                    "format_version": "1.2",
                    "terraform_version": "1.12.5",
                    "resource_changes": [{"address": "a.b", "change": {"actions": ["create"]}}],
                }
            )
        )
        result = await pipeline.run(doc)
        assert result.stages_run == ("syntax", "schema")
        assert not result.fatal

    async def test_fatal_short_circuits(self):
        # Empty plan triggers FATAL in syntax, so schema should NOT run
        pipeline = ValidationPipeline([SyntaxStage(), SchemaStage()])
        doc = PlanDocument(raw={}, format_version="", terraform_version="")
        result = await pipeline.run(doc)
        assert result.fatal
        assert result.stages_run == ("syntax",)  # schema not reached
        assert any(f.code == "EMPTY_PLAN" for f in result.findings)

    async def test_non_fatal_accumulates(self):
        doc = PlanDocument.from_json(
            json.dumps(
                {
                    "format_version": "1.2",
                    "resource_changes": [{"address": "a.b"}],  # missing change field
                }
            )
        )
        pipeline = ValidationPipeline([SyntaxStage(), SchemaStage()])
        result = await pipeline.run(doc)
        assert not result.fatal
        assert result.stages_run == ("syntax", "schema")
        # Should have findings from both stages
        assert any(f.code == "MISSING_TERRAFORM_VERSION" for f in result.findings)
        assert any(f.code == "MISSING_CHANGE" for f in result.findings)

    async def test_real_sample(self):
        """Pipeline over the real plan-sample.json."""
        if not PLAN_SAMPLE_PATH.exists():
            pytest.fail(
                "agent/testdata/plan-sample.json is committed and is criterion 13's "
                "only fixture; a missing file must fail, not skip"
            )
        data = PLAN_SAMPLE_PATH.read_text(encoding="utf-8")
        doc = PlanDocument.from_json(data)
        pipeline = ValidationPipeline()
        result = await pipeline.run(doc)
        assert not result.fatal
        assert result.stages_run == ("syntax", "schema")
        # Real sample should have no errors
        errors = [f for f in result.findings if f.severity in (Severity.ERROR, Severity.FATAL)]
        assert len(errors) == 0
